import {MAP2_AUDIO_LEVELS} from './map2-audio-levels.mjs';
import {MAP2_SAMPLES,MAP2_REGIONS} from './map2-audio-config.mjs';
export const MAP2_AUDIO_EVENTS=Object.freeze({jump:'jump',spore:'spore',bounce:'bounce',hurt:'hurt','projectile-hurt':'hurt',fire:'emitter-fire',telegraph:'emitter-warn','drum-fill':'drum-fill',drumsticks:'drumsticks-get','secret-enter':'studio-enter','secret-exit':'studio-exit','art-card':'card-reveal'});
export function danceSoundEvents(d){return d.schedule.flatMap((t,s)=>[...d.stages[s].sequence.map((direction,i)=>({key:`${s}:demo:${i}`,id:`demo-${direction}`,clock:t.demoAt+i*500})),...[0,1,2,3].map(i=>({key:`${s}:count:${i}`,id:'dance-count',clock:t.countAt+i*500,variant:i}))]);}
export class Map2SampleAudio{
 constructor({factory=()=>new AudioContext(),fetcher=(...a)=>fetch(...a),hidden=()=>document.hidden}={}){this.factory=factory;this.fetcher=fetcher;this.hidden=hidden;this.context=null;this.buffers=new Map;this.errors=new Set;this.active=new Set;this.enabled=true;this.focused=true;this.volume=MAP2_AUDIO_LEVELS.sfx;this.pauseVolume=MAP2_AUDIO_LEVELS.bgm;this.loop=null;this.game=null;this.log=[];this.seen=new Set;this.dance=null;this.ready=false;this.last=new Map;}
 async unlock(){if(!this.enabled)return;try{this.context??=this.factory();if(this.context.state==='suspended')await this.context.resume();this.pending??=Promise.all(Object.entries(MAP2_SAMPLES).map(async([id,file])=>{try{const res=await this.fetcher(new URL('../audio/map2-sfx-v1/'+file,import.meta.url));if(!res.ok)throw Error(res.status);this.buffers.set(id,await this.context.decodeAudioData(await res.arrayBuffer()));}catch{this.errors.add(id)}})).then(()=>{this.ready=true;this.prepareLoop()});await this.pending;}catch{}}
 prepareLoop(){const b=this.buffers.get('pause-loop');if(!b)return;const start=Math.round(.12*b.sampleRate),end=Math.min(b.length,Math.round(61.5*b.sampleRate)),overlap=Math.round(.12*b.sampleRate),n=end-start;if(n<=overlap)return;const out=this.context.createBuffer(b.numberOfChannels,n-overlap,b.sampleRate);for(let ch=0;ch<b.numberOfChannels;ch++){const src=b.getChannelData(ch).subarray(start,end),dst=out.getChannelData(ch);dst.set(src.subarray(overlap));for(let i=0;i<overlap;i++){const t=i/(overlap-1);dst[dst.length-overlap+i]=src[n-overlap+i]*(1-t)+src[i]*t}}this.loopBuffer=out;this.buffers.delete('pause-loop');}
 setEnabled(v){this.enabled=!!v;if(!v)this.stopAll();}
 stopAll(){for(const s of [...this.active]){if(s.danceKey&&s.startAt>this.context.currentTime)this.seen.delete(s.danceKey);try{s.stop()}catch{}}this.active.clear();this.loop=null;}
 updateGame(g){if(this.game!==g){this.stopAll();this.game=g;this.dance=null;this.seen.clear()}if(!this.enabled||this.hidden()||!this.focused){this.stopAll();return}if(g.mode==='paused'){if(this.lastMode!=='paused')this.stopAll();this.startPause();}else if(this.loop){const s=this.loop,now=this.context.currentTime;s.pauseGain.gain.cancelScheduledValues(now);s.pauseGain.gain.setValueAtTime(s.pauseGain.gain.value,now);s.pauseGain.gain.linearRampToValueAtTime(0,now+.06);s.stop(now+.06);this.loop=null;}this.lastMode=g.mode;}
 startPause(){if(this.loop||!this.loopBuffer||this.context?.state!=='running')return;const s=this.context.createBufferSource(),gain=this.context.createGain();s.buffer=this.loopBuffer;s.loop=true;gain.gain.setValueAtTime(0,this.context.currentTime);gain.gain.linearRampToValueAtTime(this.pauseVolume,this.context.currentTime+.08);s.connect(gain).connect(this.context.destination);s.onended=()=>{this.active.delete(s);s.disconnect();gain.disconnect()};s.pauseGain=gain;this.loop=s;this.active.add(s);s.start();this.record({id:'pause-loop',loop:true});}
 record(e){this.log.push({...e,at:this.context.currentTime});if(this.log.length>250)this.log.shift()}
 play(id,{at,variant=0,key}={}){if(!this.enabled||this.hidden()||!this.focused||this.game?.mode==='paused')return true;const b=this.buffers.get(id);if(!b||this.context?.state!=='running')return false;const now=this.context.currentTime;if(!key&&now-(this.last.get(id)??-Infinity)<(id==='button'||id==='ui-back'?0.08:0.04))return true;this.last.set(id,now);let count=0;for(const s of this.active)if(s.sampleId===id)count++;if(count>=4)return true;const region=MAP2_REGIONS[id]??{offset:0,duration:b.duration},offset=region.offsets?.[variant]??region.offset,duration=Math.min(region.duration,b.duration-offset);const s=this.context.createBufferSource(),gain=this.context.createGain(),when=Math.max(now,at??now);s.buffer=b;s.sampleId=id;s.danceKey=key;s.startAt=when;gain.gain.setValueAtTime(this.volume,when);gain.gain.setValueAtTime(this.volume,Math.max(when,when+duration-.012));gain.gain.linearRampToValueAtTime(0,when+duration);s.connect(gain).connect(this.context.destination);s.onended=()=>{this.active.delete(s);s.disconnect();gain.disconnect()};this.active.add(s);s.start(when,offset,duration);this.record({id,scheduledAt:when,offset,duration,key});return true;}
 stopDance(){for(const s of this.active)if(s.danceKey){try{s.stop()}catch{}}this.dance=null;this.seen.clear();}
 handleEvent(event,g){this.updateGame(g);if(g.mapId!==2&&!(g.mapId===4&&event==='advanced-clear'))return false;const id=event==='advanced-clear'?'card-reveal':event.startsWith('checkpoint-')?'checkpoint':MAP2_AUDIO_EVENTS[event];if(!id)return false;if(event==='fire')for(const s of this.active)if(s.sampleId==='emitter-warn'){try{s.stop()}catch{}}return this.play(id);}
 syncDance(d,media){if(!this.context||!this.ready||!this.enabled||!d||!media.musicStarted||media.paused||this.game?.mode==='paused'||this.hidden())return;if(this.dance!==d){this.dance=d;this.seen.clear()}const now=media.clock();for(const e of danceSoundEvents(d)){if(this.seen.has(e.key))continue;if(e.clock<now-80){this.seen.add(e.key);continue}if(e.clock<=now+120&&this.play(e.id,{at:this.context.currentTime+(e.clock-now)/1000,variant:e.variant,key:e.key}))this.seen.add(e.key)}if(d.feedback){const key=`${d.stageIndex}:result`;if(!this.seen.has(key)){const id={success:'round-good',partial:'round-partial',retry:'round-retry'}[d.feedback.outcome];if(this.play(id,{key}))this.seen.add(key)}}}
}
